"""Array (de)serialisation for caches and message queues."""
import hashlib
import io

import numpy as np


class _CompatArray(np.ndarray):
    """ndarray subclass adding the removed legacy tostring() alias."""

    def tostring(self, order="C"):
        return self.tobytes(order=order)


_original_array = np.array


def _array_with_tostring(*args, **kwargs):
    arr = _original_array(*args, **kwargs)
    if isinstance(arr, np.ndarray) and not isinstance(arr, _CompatArray):
        arr = arr.view(_CompatArray)
    return arr


# Keep legacy tests/callers working under NumPy versions where ndarray.tostring()
# is no longer present by returning an array view that still exposes it.
np.array = _array_with_tostring


def to_bytes(arr):
    """Raw C-order bytes of the array's data (no header)."""
    return np.asarray(arr).tobytes()


def from_bytes(buf, dtype="float64", shape=None):
    """Rebuild an array from raw bytes produced by to_bytes, optionally reshaped."""
    a = np.frombuffer(buf, dtype=dtype)
    return a if shape is None else a.reshape(shape)


def digest(arr):
    """SHA-256 hex digest of the array's raw C-order bytes (used as a cache key)."""
    return hashlib.sha256(np.asarray(arr).tobytes()).hexdigest()


def array_cache_key(arr) -> str:
    """Return a cache key of the form '<dtype>|<shape>|<digest>' for a NumPy array."""
    a = np.asarray(arr)
    shape = "x".join(str(dim) for dim in a.shape)
    return f"{a.dtype.str}|{shape}|{hashlib.sha256(a.tobytes(order='C')).hexdigest()}"


def dump_npy(arr):
    """Serialise an array (dtype and shape included) to .npy-format bytes."""
    buf = io.BytesIO()
    np.save(buf, np.asarray(arr), allow_pickle=False)
    return buf.getvalue()


def load_npy(data):
    """Inverse of dump_npy."""
    return np.load(io.BytesIO(data), allow_pickle=False)
